steps.message:
Execute: adb shell "sqlite3 /data/user/0/com.flauschcode.broccoli/databases/broccoli <<'SQL'
.headers on
.mode column
SELECT recipeId,title,imageName,description,servings,preparationTime,source,substr(ingredients,1,40) AS ingredients_prefix,substr(directions,1,60) AS directions_prefix,favorite FROM recipes ORDER BY recipeId LIMIT 12;
SELECT favorite, COUNT(*) AS cnt FROM recipes GROUP BY favorite;
SELECT COUNT(*) AS total_recipes FROM recipes;
SELECT COUNT(*) AS total_links FROM recipes_with_categories;
SELECT r.recipeId,r.title,COUNT(rwc.categoryId) AS category_links FROM recipes r LEFT JOIN recipes_with_categories rwc ON r.recipeId=rwc.recipeId GROUP BY r.recipeId,r.title ORDER BY r.recipeId LIMIT 12;
SQL"

